%[text] # **Deflection Analysis of Bracket**
%[text] The same three-dimensional bracket is solved with MATLAB PDE Toolbox and OpenSeesMatlab. Reusing one mesh makes the comparison focus on boundary conditions, material data, load transfer, and displacement results.
%[text] A three-dimensional bracket is loaded to determine its displacement field and maximum deflection.
%[text] Matlab examples see \[Partial Differential Equation Toolbox\](https://www.mathworks.com/help/pde/ug/deflection-analysis-of-bracket-femodel.html).
%[text] ### Partial Differential Equation Toolbox Solving
clc; clear;

E  = 200e9;
nu = 0.3;
rho = 0.0;

model = femodel(AnalysisType="structuralStatic", ...
                Geometry="BracketWithHole.stl");

model.MaterialProperties = materialProperties( ...
    YoungsModulus = E, ...
    PoissonsRatio = nu);

model.FaceBC(4) = faceBC(Constraint="fixed");
model.FaceLoad(8) = faceLoad(SurfaceTraction=[0;0;-1e4]);

figure %[output:3c3d41a7]
pdegplot(model,FaceLabels="on"); %[output:3c3d41a7]
view(30,30); %[output:3c3d41a7]
title("Bracket with Face Labels") %[output:3c3d41a7]
pdeModel = generateMesh(model, GeometricOrder="linear");

figure %[output:8601b5b0]
pdemesh(pdeModel); %[output:8601b5b0]
title("Mesh with Linear Tetrahedral Elements") %[output:8601b5b0]
result = solve(pdeModel);
minUzPDE = min(result.Displacement.uz);
fprintf("Maximal deflection in the z-direction is %g meters.",minUzPDE) %[output:5a80c41a]
figure %[output:6d735716]
pdeplot3D(result.Mesh,ColorMapData=result.Displacement.uz); %[output:6d735716]
title("z-displacement"); %[output:6d735716]
colormap("jet") %[output:6d735716]
[az, el] = view;
figure %[output:35b237cc]
pdeplot3D(result.Mesh,ColorMapData=result.VonMisesStress) %[output:35b237cc]
title("von Mises stress") %[output:35b237cc]
colormap("jet") %[output:35b237cc]
maxVonMisesStressPDE = max(result.VonMisesStress);
fprintf("Maximal VonMisesStress is %g Pa.", maxVonMisesStressPDE) %[output:65b41429]
%[text] ### OpenSeesMatlab Solving
%[text] #### Extract PDE mesh data
mesh = pdeModel.Mesh;

% PDE toolbox:
%   mesh.Nodes    : 3 x nNode
%   mesh.Elements : nNodePerElem x nElem
nodes = mesh.Nodes.';        % nNode x 3
elems = mesh.Elements.';     % nElem x nen

nNode = size(nodes,1);
nElem = size(elems,1);
nen   = size(elems,2);

if nen ~= 4
    error(['This script currently expects linear 4-node tetrahedra. ', ...
           'Please use generateMesh(..., GeometricOrder="linear").']);
end

%% ------------------------------------------------------------------------
% Find face nodes for fixed boundary and loaded boundary
%% ------------------------------------------------------------------------
fixedFaceID  = 4;
loadedFaceID = 8;
traction     = [0; 0; -1e4];   % N/m^2

fixedNodeIDs = findNodes(mesh, "region", "Face", fixedFaceID);
loadNodeIDs  = findNodes(mesh, "region", "Face", loadedFaceID);

fixedNodeIDs = unique(fixedNodeIDs(:));
loadNodeIDs  = unique(loadNodeIDs(:));

%% ------------------------------------------------------------------------
% Build boundary triangles on the loaded face and convert traction
%    to equivalent nodal loads
%% ------------------------------------------------------------------------
% For a tetra mesh, each tetra has 4 triangular faces.
% Boundary faces are those triangle faces that appear only once.
allBoundaryTris = getBoundaryTrianglesFromTets(elems);

% Keep only boundary triangles whose 3 nodes are all on Face 8
isOnLoadFace = all(ismember(allBoundaryTris, loadNodeIDs.'), 2);
loadFaceTris = allBoundaryTris(isOnLoadFace, :);

if isempty(loadFaceTris)
    warning('No boundary triangles were found on loaded Face %d.', loadedFaceID);
end

% Assemble nodal force vector from surface traction
nodalLoads = zeros(nNode, 3);

for i = 1:size(loadFaceTris,1)
    tri = loadFaceTris(i,:);
    xyz = nodes(tri, :);              % 3 x 3
    A   = triangleArea3D(xyz);

    % Constant traction on linear triangle:
    % equivalent nodal load = traction * A / 3 for each of 3 nodes
    fe = (A / 3) * traction(:);       % 3 x 1 for one node
    nodalLoads(tri, :) = nodalLoads(tri, :) + repmat(fe.', 3, 1);
end
%[text] #### Build OpenSees model
opsMAT = OpenSeesMatlab(); %[output:7e22b8cc]
ops = opsMAT.opensees;

ops.wipe();
ops.model('basic', '-ndm', 3, '-ndf', 3);

% Nodes
for i = 1:nNode
    ops.node(i, nodes(i,1), nodes(i,2), nodes(i,3));
end

% Material
matTag = 1;
E  = 200e9;
nu = 0.3;
rho = 0.0;

% 3D isotropic elastic material
ops.nDMaterial('ElasticIsotropic', matTag, E, nu, rho);

% Elements: 4-node tetrahedra
for e = 1:nElem
    n = elems(e,:);
    ops.element('FourNodeTetrahedron', e, n(1), n(2), n(3), n(4), matTag);
end

% Apply fixed boundary from PDE Face 4
for k = 1:numel(fixedNodeIDs)
    nd = fixedNodeIDs(k);
    ops.fix(nd, 1, 1, 1);
end

% Apply equivalent nodal loads from PDE Face 8 traction
ops.timeSeries('Linear', 1);
ops.pattern('Plain', 1, 1);

tol = 0;
for i = 1:nNode
    fx = nodalLoads(i,1);
    fy = nodalLoads(i,2);
    fz = nodalLoads(i,3);

    if abs(fx) > tol || abs(fy) > tol || abs(fz) > tol
        ops.load(i, fx, fy, fz);
    end
end
% Static analysis
Nsteps = 2;
ops.constraints('Plain');
ops.numberer('RCM');
ops.system('BandGeneral');
ops.test('NormDispIncr', 1e-8, 50);
ops.algorithm('Linear');
ops.integrator('LoadControl', 1.0/Nsteps);
ops.analysis('Static');

ODB = opsMAT.post.createODB("myODB");  % create ODB %[output:06cb3783]
ok = ops.analyze(Nsteps);
%ODB.close();
%[text] #### Visualization by OpenSeesMatlab
opts = opsMAT.vis.defaultPlotModelOptions;
opts.loads.showNodal=true;
opsMAT.vis.plotModel(opts=opts); %[output:71b85a1b] %[output:1103d61a]
view(az, el); %[output:1103d61a]
nodeResp = opsMAT.post.getNodalResponse("myODB");
uz = nodeResp.disp.uz;
minUz = min(uz(:));
fprintf("Maximal deflection in the z-direction:\n" + ... %[output:group:4fc8dbd3] %[output:8f634035]
        "  OpenSeesMatlab: %g meters\n" + ... %[output:8f634035]
        "  MATLAB PDE    : %g meters\n", ... %[output:8f634035]
        minUz, minUzPDE); %[output:group:4fc8dbd3] %[output:8f634035]
opts = opsMAT.vis.defaultPlotNodalResponseOptions;
opts.fixed.show = false;
opts.surf.showEdges = false;

opsMAT.vis.plotNodalResponse(nodeResp, respType="disp", stepIdx="absMax", respComponent="UZ", opts=opts); %[output:9b984d2d]
colormap("jet") %[output:9b984d2d]
axis off %[output:9b984d2d]
view(az, el); %[output:9b984d2d]
solidResp = opsMAT.post.getElementResponse("myODB", eleType="Solid");
vm = solidResp.StressMeasureAtNode.vonMises;
maxVonMisesStress = max(vm(:));
fprintf("Maximal Von Mises stress:\n" + ... %[output:group:86306409] %[output:8cb633b8]
        "  OpenSeesMatlab: %g Pa\n" + ... %[output:8cb633b8]
        "  MATLAB PDE    : %g Pa\n", ... %[output:8cb633b8]
        maxVonMisesStress, maxVonMisesStressPDE); %[output:group:86306409] %[output:8cb633b8]
opts = opsMAT.vis.defaultPlotContinuumResponseOptions;
opts.fixed.show = false;
opts.surf.showEdges = false;

opsMAT.vis.plotContinuumResponse(solidResp, stepIdx="absMax",... %[output:1046798d]
    respType="StressMeasureAtNode", respComponent="vonMises", opts=opts); %[output:1046798d]
axis off %[output:1046798d]
colormap("jet") %[output:1046798d]
view(az, el); %[output:1046798d]
% opsMAT.post.writeResponsePVD("myODB");
%[text] ### Visualization by Polyscope GUI
opsMAT.vis.polyscope.plotModel();
opsMAT.vis.polyscope.plotNodalResponse(nodeResp);

opsMAT.vis.polyscope.plotContinuumResponse(solidResp);
%[text] ### Local functions
%% ------------------------------------------------------------------------
% Local functions
%% ------------------------------------------------------------------------
%%
function btris = getBoundaryTrianglesFromTets(tets)
%GETBOUNDARYTRIANGLESFROMTETS Return unique boundary triangle faces
% tets: nElem x 4

    f1 = tets(:, [1 2 3]);
    f2 = tets(:, [1 2 4]);
    f3 = tets(:, [1 3 4]);
    f4 = tets(:, [2 3 4]);

    allFaces = [f1; f2; f3; f4];
    allFacesSorted = sort(allFaces, 2);

    [uFaces, ~, ic] = unique(allFacesSorted, 'rows');
    counts = accumarray(ic, 1);

    isBoundary = counts(ic) == 1;
    boundaryFacesSorted = allFacesSorted(isBoundary, :);

    % Keep orientation-free representation
    btris = boundaryFacesSorted;
end

function A = triangleArea3D(xyz)
%TRIANGLEAREA3D Area of a 3D triangle
% xyz: 3 x 3, each row is one node coordinate

    v1 = xyz(2,:) - xyz(1,:);
    v2 = xyz(3,:) - xyz(1,:);
    A = 0.5 * norm(cross(v1, v2));
end

